 * Splits raw stdin text into the three documents it holds, throwing a
 * `ParseError` when the input does not separate cleanly into exactly three
 * parts on lines that read exactly `%%%`.
 */
export class ParseError extends Error {}

export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }

  if (parts.length !== 3) throw new ParseError('expected three parts separated by %%%')
  return parts
}
"}

